namespace ghidra.app.plugin.core.debug.gui;






using docking;
using docking.widgets.table;
using docking.widgets.table;
using ghidra.framework.plugintool;
using ghidra.util.table;

public abstract class AbstractDebuggerMapProposalDialog<R> : ReusableDialogComponentProvider {
	protected static readonly int BUTTON_SIZE = 32;

	protected EnumeratedColumnTableModel<R> tableModel;
	protected GTable table;
	protected GhidraTableFilterPanel<R> filterPanel;

	private Collection<R> adjusted;

	protected AbstractDebuggerMapProposalDialog(PluginTool tool, string title) : base(title, true, true, true, false)
    {
		tableModel = createTableModel(tool);
		populateComponents();
	}

	protected abstract EnumeratedColumnTableModel<R> createTableModel(PluginTool tool);

	protected void populateComponents() {
		JPanel panel = new JPanel(new BorderLayout());

		table = new GTable(tableModel);
		table.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
		panel.add(new JScrollPane(table));

		filterPanel = new(table, tableModel);
		panel.add(filterPanel, BorderLayout.SOUTH);

		addWorkPanel(panel);

		addOKButton();
		addCancelButton();

		createActions();
	}

	/* testing */
	public GTable getTable() {
		return table;
	}

	/* testing */
	public EnumeratedColumnTableModel<R> getTableModel() {
		return tableModel;
	}

	protected void removeEntry(R entry) {
		tableModel.delete(entry);
	}

	protected void createActions() {
		// Extension point
	}

	/* @Override */
	protected void okCallback() {
		adjusted = tableModel.getModelData();
		close();
	}

	/* @Override */
	protected void cancelCallback() {
		adjusted = null;
		close();
	}

	public Collection<R> getAdjusted() {
		return adjusted;
	}

	public Collection<R> adjustCollection(PluginTool tool, Collection<R> collection) {
		tableModel.clear();
		tableModel.addAll(collection);
		tool.showDialog(this);
		return getAdjusted();
	}
}
